// @vitest-environment jsdom
/**
 * The RSG store's tile mark, and the two things about it that are promises.
 *
 * It is the one shipped store drawn as a picture rather than as letters in a
 * coloured square, because it is the one whose logo is the lab's own
 * (`ui/stores/registry.ts` on `StoreMark.image`). The picture is a Hi-C map
 * with *RSG* down its diagonal, generated by `scripts/make-rsg-mark.mjs` and
 * committed as a data URI.
 *
 * The first promise is the palette. The generator is a `.mjs` script and cannot
 * import the viewer's TypeScript, so it carries its own copy of the ramp's
 * thirteen stops; the mark would keep building, and keep looking fine, long
 * after someone retuned `DEFAULT_STOPS` and left the copy behind. What that
 * costs is a logo in last year's colours next to maps drawn in this year's,
 * which is exactly the kind of drift nobody files a bug about. So the palette
 * is compared here, byte for byte, against the ramp the viewer itself uses.
 *
 * The second is that the file is a 100-bin map with writing on it and not, say,
 * an empty one: a generator edit that damped the letters away would otherwise
 * ship a blank orange square, and the tile would still render.
 */

import { describe, expect, it } from 'vitest'
import { inflateSync } from 'node:zlib'

import { applyColormap, COLORMAP_SIZE } from '@/render/colormaps'
import { RSG_MARK_IMAGE } from '@/ui/stores/rsg-mark.generated'
import { builtinStores } from '@/ui/stores/registry'
import { storeMark } from '@/ui/stores/marks'

/** Bins a side, as the brief set it and as the generator's `N` writes it. */
const N = 100

/** The PNG's chunks, by type, in a map — this file has one of each. */
function chunks(png: Buffer): Map<string, Buffer> {
  const out = new Map<string, Buffer>()
  let off = 8
  while (off < png.length) {
    const length = png.readUInt32BE(off)
    out.set(png.toString('ascii', off + 4, off + 8), png.subarray(off + 8, off + 8 + length))
    off += 12 + length
  }
  return out
}

/** Paeth's predictor, as the PNG spec defines it. */
function paeth(a: number, b: number, c: number): number {
  const p = a + b - c
  const pa = Math.abs(p - a)
  const pb = Math.abs(p - b)
  const pc = Math.abs(p - c)
  if (pa <= pb && pa <= pc) return a
  return pb <= pc ? b : c
}

/** The palette indices, one a bin, undoing the per-row filters. */
function indices(idat: Buffer): Uint8Array {
  const raw = inflateSync(idat)
  const out = new Uint8Array(N * N)
  const prev = new Uint8Array(N)
  for (let y = 0; y < N; y++) {
    const type = raw[y * (N + 1)]
    const row = raw.subarray(y * (N + 1) + 1, y * (N + 1) + 1 + N)
    const cur = new Uint8Array(N)
    for (let x = 0; x < N; x++) {
      const left = x > 0 ? cur[x - 1] : 0
      const above = prev[x]
      const upperLeft = x > 0 ? prev[x - 1] : 0
      const predictor =
        type === 0 ? 0
        : type === 1 ? left
        : type === 2 ? above
        : type === 3 ? (left + above) >> 1
        : paeth(left, above, upperLeft)
      cur[x] = (row[x] + predictor) & 0xff
    }
    out.set(cur, y * N)
    prev.set(cur)
  }
  return out
}

const png = Buffer.from(RSG_MARK_IMAGE.slice(RSG_MARK_IMAGE.indexOf(',') + 1), 'base64')
const parts = chunks(png)

describe('the RSG store mark', () => {
  it('is a 100-bin indexed PNG', () => {
    expect(RSG_MARK_IMAGE.startsWith('data:image/png;base64,')).toBe(true)
    expect([...png.subarray(0, 8)]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])
    const ihdr = parts.get('IHDR')!
    expect(ihdr.readUInt32BE(0)).toBe(N)
    expect(ihdr.readUInt32BE(4)).toBe(N)
    expect(ihdr[8]).toBe(8) // bit depth
    expect(ihdr[9]).toBe(3) // colour type: indexed, so PLTE is the ramp
  })

  it('is paletted in the viewer’s own default ramp', () => {
    const palette = parts.get('PLTE')!
    expect(palette.length).toBe(COLORMAP_SIZE * 3)
    const ramp = applyColormap('default')
    // The generator's copy of DEFAULT_STOPS against the interpolation the
    // viewer runs: every entry, because a stop edited at one end of the ramp
    // moves only the entries near it.
    const expected = Array.from({ length: COLORMAP_SIZE }, (_, i) => [
      ramp[i * 4],
      ramp[i * 4 + 1],
      ramp[i * 4 + 2],
    ])
    const got = Array.from({ length: COLORMAP_SIZE }, (_, i) => [
      palette[i * 3],
      palette[i * 3 + 1],
      palette[i * 3 + 2],
    ])
    expect(got).toEqual(expected)
  })

  it('has its letters on the diagonal and paper in the corners', () => {
    const px = indices(parts.get('IDAT')!)
    // The letters take the top of the ramp, and they are the only thing that
    // does: the hottest bin in the map is within a letter's box, every one of
    // which is centred on the diagonal.
    let hottest = 0
    for (let i = 1; i < px.length; i++) if (px[i] > px[hottest]) hottest = i
    expect(px[hottest]).toBeGreaterThan(220)
    const boxes = [4, 37, 70]
    const row = Math.floor(hottest / N)
    const column = hottest % N
    const inLetter = boxes.some(
      (at) => row >= at && row < at + 26 && column >= at && column < at + 26,
    )
    expect(inLetter).toBe(true)

    // Enough of them to be three letters rather than a speck of dirt.
    const dark = [...px].filter((v) => v > 200).length
    expect(dark).toBeGreaterThan(400)

    // And the corners furthest from the diagonal are paper, which is the decay
    // that makes the picture a contact map.
    for (const corner of [px[N - 1], px[(N - 1) * N]]) expect(corner).toBeLessThan(40)
  })

  it('is the mark the RSG store is drawn with, and the only one', () => {
    const withImages = builtinStores().filter((front) => front.mark.image !== undefined)
    expect(withImages.map((front) => front.id)).toEqual(['rsg'])
    expect(withImages[0].mark.image).toBe(RSG_MARK_IMAGE)
    // The letters stay behind it, so a mark that fails to load is not a hole.
    expect(withImages[0].mark.text).toBe('RSG')
  })

  it('reaches the tile as an image over the letters', () => {
    const rsg = builtinStores().find((front) => front.id === 'rsg')!
    // 26 is the small tile, the size at which the drawer lists the row: the
    // image is drawn at every size, so this is the one that would catch a
    // short-form rule growing to cover it.
    for (const size of [72, 26]) {
      const node = storeMark(rsg.mark, size)
      const image = node.querySelector('img')
      expect(image?.getAttribute('src')).toBe(RSG_MARK_IMAGE)
      expect(node.textContent).toBe('RSG')
    }
  })
})
